package ktanesolver.module.modded.regular.modulo;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;class ModuloSolverTest{private final ModuloSolver solver=new ModuloSolver();@Test void returnsRemainderIncludingZero(){assertThat(solve(999,15).answer()).isEqualTo(9);assertThat(solve(90,15).answer()).isZero();}@Test void acceptsExactGeneratedBounds(){assertThat(solve(50,3).answer()).isEqualTo(2);assertThat(solve(999,15).answer()).isEqualTo(9);}@Test void rejectsValuesTheSourceCannotGenerate(){assertThat(result(49,3)).isInstanceOf(SolveFailure.class);assertThat(result(1000,3)).isInstanceOf(SolveFailure.class);assertThat(result(50,2)).isInstanceOf(SolveFailure.class);assertThat(result(50,16)).isInstanceOf(SolveFailure.class);}private ModuloOutput solve(int n,int m){return((SolveSuccess<ModuloOutput>)result(n,m)).output();}private SolveResult<ModuloOutput>result(int n,int m){return solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new ModuloInput(n,m));}}
